@prefix schema: <https://schema.org/> .
@prefix wd:     <https://www.wikidata.org/entity/> .

wd:Q76  schema:name         "Barack Obama" ;
        schema:birthPlace   wd:Q37100 ;        # Honolulu
        schema:birthDate    "1961-08-04"^^xsd:date .

SELECT ?personName ?countryName WHERE {
  ?person schema:birthPlace ?country .
  ?person schema:name ?personName .
  ?country schema:name ?countryName .
  FILTER(LANG(?countryName) = 'en')
}

-- Postgres: relational + document in one table
CREATE TABLE events (
  id         BIGSERIAL PRIMARY KEY,
  occurred_at TIMESTAMPTZ NOT NULL,
  user_id    BIGINT REFERENCES users(id),
  payload    JSONB NOT NULL
);

CREATE INDEX idx_events_payload ON events USING GIN (payload);

-- Query a JSON field alongside relational columns
SELECT user_id, payload->>'action' AS action
FROM events
WHERE occurred_at > NOW() - INTERVAL '1 day'
  AND payload @> '{"category": "checkout"}';
